{
  "witnessCode": "import { test } from 'node:test';
import { strict } from 'node:assert/strict';
import x from '../index.js';

test('keepQueryParameters with single parameter should keep only that parameter', async (t) => {
  const url = 'http://example.com?a=1&b=2';
  const options = { keepQueryParameters: ['a'] };
  const result = x(url, options);
  const expected = 'http://example.com/?a=1';
  strict.equal(result, expected);
});"
}
